function timeSemanticEntity(
  id: string,
  dayId: string,
  title: string,
  time: TripTime,
  semanticType: SemanticType = "activity",
): CanonicalEntity {
  return {
    id,
    day_id: dayId,
    semantic_type: semanticType,
    title,
    place: { name: null, address: null, url: null, unresolved: false },
    time,
    state: {
      optional: false,
      tentative: false,
      flexible: semanticType === "free_time",
      unresolved: false,
    },
    reservation: null,
    ticket: null,
    readiness: null,
    notes: [],
    actions: [],
    provenance: {
      origin: "source",
      overridden_fields: [],
      source_id: "source:time-semantics",
      locator_refs: [`source:${id}`],
    },
  };
}

